Web VPython 3.2
def f(a, b) :
    return (a.pos.x-b.pos.x)**2 + (a.pos.y-b.pos.y)**2 <= (a.radius + b.radius)**2

x = sphere(color = color.magenta, make_trail = True)
y = sphere(color = color.cyan)

while True :
    rate(100)
    k = keysdown()
    if 'left' in k : 
        x.pos.x = x.pos.x - 0.1
    if 'right' in k : 
        x.pos.x = x.pos.x + 0.1
    if 'up' in k : 
        x.pos.y += 0.1
    if 'down' in k : 
        x.pos.y -= 0.1
    if f(x, y) : 
        y.color = color.red
        y.opacity = 0.5
    else : 
        y.color = color.cyan
        y.opacity = 1

    if 'q' in k : 
        label(text = 'The End')
        break

